package at.hausgarten.service;

import org.json.*;
import java.io.IOException;

/** Actual source projections, explicit selection and conflicting-source rejection; no browser or database simulation. */
public final class RestoredBrowserReviewRulesTests {
    static int checks;static void yes(boolean value){checks++;if(!value)throw new AssertionError("Restored browser review "+checks);}
    static void refused(JSONObject browser)throws Exception{try{RestoredBrowserReviewRules.validate(browser);throw new AssertionError("Expected invalid browser rejection");}catch(IOException|JSONException expected){checks++;}}
    static JSONObject browser(String value)throws Exception{return new JSONObject().put("formatVersion",1).put("storage",new JSONObject().put("hausgarten.entry.draft.v1",new JSONObject().put("activity",value).toString()).put("qa_old_business_cache","QA archived only").put("hausgarten.offer.order.action.v1","QA old action never activated"));}
    public static void main(String[] args)throws Exception {
        SyntheticBusinessData.verify();JSONObject backup=browser("QA backup work"),device=browser("QA device work");String beforeBackup=backup.toString(),beforeDevice=device.toString();
        yes(RestoredBrowserReviewRules.validate(backup).toString().equals(beforeBackup));yes(RestoredBrowserReviewRules.drafts(backup).length()==1);yes(!RestoredBrowserReviewRules.selectable("qa_old_business_cache"));yes(!RestoredBrowserReviewRules.selectable("hausgarten.offer.order.action.v1"));yes(!RestoredBrowserReviewRules.selectable("qa_accessToken"));yes(RestoredBrowserReviewRules.selectable("hausgarten.garden.draft.qa_customer"));yes(!RestoredBrowserReviewRules.selectable("hausgarten.garden.draft.../qa_escape"));
        yes(RestoredBrowserReviewRules.selection(backup,device,new JSONArray()).length()==0);JSONObject choice=new JSONObject().put("source","backup").put("key","hausgarten.entry.draft.v1");JSONObject selected=RestoredBrowserReviewRules.selection(backup,device,new JSONArray().put(choice));yes(selected.getString("hausgarten.entry.draft.v1").contains("QA backup work"));yes(RestoredBrowserReviewRules.selection(backup,device,new JSONArray().put(new JSONObject(choice.toString()).put("source","device"))).getString("hausgarten.entry.draft.v1").contains("QA device work"));
        for(JSONArray invalid:new JSONArray[]{new JSONArray().put(choice).put(new JSONObject(choice.toString()).put("source","device")),new JSONArray().put(new JSONObject(choice.toString()).put("source","other")),new JSONArray().put(new JSONObject(choice.toString()).put("key","qa_old_business_cache")),new JSONArray().put(new JSONObject(choice.toString()).put("key","hausgarten.payment.editor.v1"))})try{RestoredBrowserReviewRules.selection(backup,device,invalid);throw new AssertionError("Expected explicit choice rejection");}catch(IOException expected){checks++;}
        yes(backup.toString().equals(beforeBackup)&&device.toString().equals(beforeDevice));refused(new JSONObject(backup.toString()).put("formatVersion",2));refused(new JSONObject(backup.toString()).put("storage",new JSONObject().put("qa_number",1)));refused(new JSONObject(backup.toString()).put("drafts",new JSONObject().put("formatVersion",1)));
        JSONObject field=new JSONObject().put("id","qa_activity").put("name","activity").put("value","QA unmirrored active form"),form=new JSONObject().put("key","qa_work").put("identity",new JSONArray()).put("fields",new JSONArray().put(field)),visible=new JSONObject().put("formatVersion",1).put("page","qa_work_page").put("forms",new JSONArray().put(form));backup.put("drafts",visible);JSONObject projected=RestoredBrowserReviewRules.drafts(backup);yes(projected.getString(RestoredBrowserReviewRules.MIRROR).contains("QA unmirrored active form"));yes(projected.getString(RestoredBrowserReviewRules.MIRROR).contains("qa_work_page"));yes(!backup.getJSONObject("storage").has(RestoredBrowserReviewRules.MIRROR));yes(RestoredBrowserReviewRules.candidates(backup,"backup").length()==2);
        JSONObject bad=new JSONObject(backup.toString());bad.getJSONObject("drafts").getJSONArray("forms").getJSONObject(0).getJSONArray("fields").getJSONObject(0).put("value",7);refused(bad);JSONObject brokenMirror=browser("QA");brokenMirror.getJSONObject("storage").put(RestoredBrowserReviewRules.MIRROR,"{");refused(brokenMirror);JSONObject futureMirror=browser("QA");futureMirror.getJSONObject("storage").put(RestoredBrowserReviewRules.MIRROR,new JSONObject().put("formatVersion",2).put("pages",new JSONObject()).toString());refused(futureMirror);
        yes(RestoredBrowserReviewRules.label("hausgarten.entry.draft.v1").equals("Arbeitsaufzeichnung"));yes(!RestoredBrowserReviewRules.label("hausgarten.entry.draft.v1").contains("hausgarten"));
        System.out.println("PASS "+checks+" restored-browser strict source/visible-form projection/explicit source selection/conflict/no old actions/no mutation checks; no database or device claim");
    }
}
